// # an import cycle: a bounded protocol extends its peer's bounded protocol
// def cycle(c: bnd_cyc_q.Counted[int32]) -> int32:
//     return c.size() + c.count() + bnd_cyc_p.peer_tag()
template<::tpyapp::bnd_cyc_q::Counted<int32_t> T_c>
int32_t cycle(T_c&& c) {
    return (::tpy::add_check<int32_t>((::tpy::add_check<int32_t>(c.size(), c.count())), ::tpyapp::bnd_cyc_p::peer_tag()));
}

